def _generate_expression(self):
    # turn my _format attribute into the _expression attribute
    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # this will be a braces-delimited field to handle
            # Validate that the field is properly enclosed
            if not part.endswith('}'):
                raise ValueError(f"unclosed brace in format: {part!r}")
            e.append(self._handle_field(part))
        else:
            # just some text to match
            # Check for unmatched closing braces
            if '}' in part:
                raise ValueError(f"unmatched closing brace in format: {part!r}")
            e.append(REGEX_SAFETY.sub(self._regex_replace, part))
    return ''.join(e)

